#!/usr/bin/env bash
# Print the Homebrew cask for a Headway release.
# Usage: homebrew-cask.sh <version> <dir with headway_<version>_<os>_<arch>.tar.gz files>
set -euo pipefail
version="$1"
dist="$2"

sha() { sha256sum "$dist/headway_${version}_$1.tar.gz" | cut -d' ' -f1; }
url() { echo "https://github.com/cnu/headway/releases/download/v#{version}/headway_#{version}_$1.tar.gz"; }

cat <<EOF
# Generated by the Headway release workflow (cnu/headway). DO NOT EDIT.
cask "headway" do
  version "$version"

  on_macos do
    on_arm do
      sha256 "$(sha darwin_arm64)"
      url "$(url darwin_arm64)"
    end
    on_intel do
      sha256 "$(sha darwin_amd64)"
      url "$(url darwin_amd64)"
    end
  end
  on_linux do
    on_arm do
      sha256 "$(sha linux_arm64)"
      url "$(url linux_arm64)"
    end
    on_intel do
      sha256 "$(sha linux_amd64)"
      url "$(url linux_amd64)"
    end
  end

  name "Headway"
  desc "Fast, friendly native Git client with workspaces"
  homepage "https://github.com/cnu/headway"

  livecheck do
    skip "Auto-generated on release."
  end

  binary "headway"

  postflight do
    if OS.mac?
      system_command "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "#{staged_path}/headway"]
    end
  end
end
EOF
